/**
 * Denormalised search index kept in step by `SearchService`.
 */
import { and, count, desc, eq, inArray, isNull, like, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { comments, getDb, issues, projects, searchIndex } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { compact, keysetPredicate, probeLimit, toPage } from "./_paging";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchIndexRow } from "@/server/db/schema/webhooks";
import type { IsoTimestamp, OrgId, Page, ProjectId } from "@/types/common";
import type { SQL } from "drizzle-orm";

/**
 * Upsert by (org, kind, subject) rather than by row id: the indexer is called
 * on every write and must be idempotent.
 */
export async function upsertSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
  content: string,
  projectId: ProjectId | null,
): Promise<void> {
  const db = getDb();
  const indexedAt = toIsoTimestamp(new Date());

  const existing = db
    .select({ id: searchIndex.id })
    .from(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .get();

  if (existing) {
    db.update(searchIndex)
      .set({ content, projectId, indexedAt })
      .where(eq(searchIndex.id, existing.id))
      .run();
    return;
  }

  db.insert(searchIndex)
    .values({
      id: newId(),
      orgId,
      subjectKind,
      subjectId,
      projectId,
      content,
      indexedAt,
    })
    .run();
}

export async function deleteSearchDocument(
  orgId: OrgId,
  subjectKind: SearchSubjectKind,
  subjectId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, subjectKind),
        eq(searchIndex.subjectId, subjectId),
      ),
    )
    .run();
}

/** Removes the comment documents of one issue (issue archived or hidden). */
export async function deleteCommentDocumentsForIssue(
  orgId: OrgId,
  issueId: string,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        eq(searchIndex.subjectKind, "comment"),
        inArray(
          searchIndex.subjectId,
          getDb()
            .select({ id: comments.id })
            .from(comments)
            .where(
              and(
                orgPredicate(comments.orgId, orgId),
                eq(comments.issueId, issueId),
              ),
            ),
        ),
      ),
    )
    .run();
}

/**
 * Removes everything that hangs off one project: the project document, the
 * documents of all its issues (archived or not) and their comments.
 */
export async function deleteSearchDocumentsForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<void> {
  const db = getDb();

  const projectIssues = db
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    );

  const projectComments = db
    .select({ id: comments.id })
    .from(comments)
    .innerJoin(issues, eq(issues.id, comments.issueId))
    .where(
      and(orgPredicate(comments.orgId, orgId), eq(issues.projectId, projectId)),
    );

  db.delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        or(
          and(
            eq(searchIndex.subjectKind, "project"),
            eq(searchIndex.subjectId, projectId),
          ),
          and(
            eq(searchIndex.subjectKind, "issue"),
            inArray(searchIndex.subjectId, projectIssues),
          ),
          and(
            eq(searchIndex.subjectKind, "comment"),
            inArray(searchIndex.subjectId, projectComments),
          ),
        ),
      ),
    )
    .run();
}

/**
 * Rebuild sweep: drops every document of one org that was not written since
 * `cutoff`. Writers stamp `indexed_at` on each upsert, so anything older was
 * not produced by the current pass and no longer belongs in the index.
 */
export async function deleteSearchDocumentsIndexedBefore(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<void> {
  getDb()
    .delete(searchIndex)
    .where(
      and(
        orgPredicate(searchIndex.orgId, orgId),
        like(searchIndex.indexedAt, "%"),
        isNull(searchIndex.id) === undefined ? undefined : undefined,
        sqlBefore(searchIndex.indexedAt, cutoff),
      ),
    )
    .run();
}

/**
 * The visibility rule over the source tables: a document is searchable only
 * while it and every row above it are live. Applied at query time so results
 * and `total` never depend on whether the index has caught up with a write.
 */
function liveSubjectPredicate(orgId: OrgId): SQL | undefined {
  const db = getDb();

  const liveProjects = db
    .select({ id: projects.id })
    .from(projects)
    .where(
      and(orgPredicate(projects.orgId, orgId), isNull(projects.archivedAt)),
    );

  const liveIssues = db
    .select({ id: issues.id })
    .from(issues)
    .innerJoin(projects, eq(projects.id, issues.projectId))
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNull(issues.archivedAt),
        isNull(projects.archivedAt),
      ),
    );

  const liveComments = db
    .select({ id: comments.id })
    .from(comments)
    .innerJoin(issues, eq(issues.id, comments.issueId))
    .innerJoin(projects, eq(projects.id, issues.projectId))
    .where(
      and(
        orgPredicate(comments.orgId, orgId),
        isNull(comments.archivedAt),
        isNull(issues.archivedAt),
        isNull(projects.archivedAt),
      ),
    );

  return or(
    and(
      eq(searchIndex.subjectKind, "project"),
      inArray(searchIndex.subjectId, liveProjects),
    ),
    and(
      eq(searchIndex.subjectKind, "issue"),
      inArray(searchIndex.subjectId, liveIssues),
    ),
    and(
      eq(searchIndex.subjectKind, "comment"),
      inArray(searchIndex.subjectId, liveComments),
    ),
  );
}

/**
 * Substring match over the denormalised content column. Deliberately simple —
 * the index is a convenience layer, not a search engine, and the tenant filter
 * is what actually matters here.
 */
export async function searchDocuments(
  input: SearchQueryInput,
): Promise<Page<SearchIndexRow>> {
  const db = getDb();
  const sort = { sortColumn: searchIndex.indexedAt, idColumn: searchIndex.id };

  const filters = compact(
    orgPredicate(searchIndex.orgId, input.orgId),
    liveSubjectPredicate(input.orgId),
    like(searchIndex.content, `%${input.q}%`),
    input.kinds.length === 0
      ? undefined
      : inArray(searchIndex.subjectKind, [...input.kinds]),
    input.projectId === undefined
      ? undefined
      : eq(searchIndex.projectId, input.projectId),
  );

  const total = db
    .select({ value: count() })
    .from(searchIndex)
    .where(and(...filters))
    .get();

  const rows = db
    .select()
    .from(searchIndex)
    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
    .orderBy(desc(searchIndex.indexedAt), desc(searchIndex.id))
    .limit(probeLimit(input.limit))
    .all();

  return toPage(
    rows,
    input.limit,
    total?.value ?? 0,
